@_ods_cext.register_operation(_Dialect)
class LcmOp(_ods_ir.OpView):
  r"""
  Computes the least common multiple of two signless integers using Euclid's
  algorithm. Both operands and the result share the same integer type.
  
  Folds aggressively: constant operands fold to a constant LCM, `lcm(x, x)`
  folds to `x`, and `lcm(x, 1)` / `lcm(1, x)` fold to the other operand.
  Dynamic survivors lower to an Euclid `gcd` loop followed by
  `lcm = (a / gcd) * b`.
  
  Example:
  ```mlir
  %m = core.lcm %a, %b : i32
  ```
  """

  OPERATION_NAME = "core.lcm"

  _ODS_REGIONS = (0, True)

  def __init__(self, lhs: _ods_ir.Value[_ods_ir.IntegerType], rhs: _ods_ir.Value[_ods_ir.IntegerType], *, results: _Optional[_Sequence[_ods_ir.Type]] = None, loc: _Optional[_ods_ir.Location] = None, ip: _Optional[_ods_ir.InsertionPoint] = None):
    operands = []
    attributes = {}
    regions = None
    operands.append(lhs)
    operands.append(rhs)
    _ods_context = _ods_get_default_loc_context(loc)
    if results is None: results = [operands[0].type] * 1
    _ods_successors = None
    super().__init__(self.OPERATION_NAME, self._ODS_REGIONS, self._ODS_OPERAND_SEGMENTS, self._ODS_RESULT_SEGMENTS, attributes=attributes, results=results, operands=operands, successors=_ods_successors, regions=regions, loc=loc, ip=ip)

  @builtins.property
  def lhs(self) -> _ods_ir.Value[_ods_ir.IntegerType]:
    return self.operation.operands[0]

  @builtins.property
  def rhs(self) -> _ods_ir.Value[_ods_ir.IntegerType]:
    return self.operation.operands[1]

  @builtins.property
  def result(self) -> _ods_ir.OpResult[_ods_ir.IntegerType]:
    return self.operation.results[0]

